package main

import "fmt"

type Shape interface {
	Area() float64
}

type Circle struct {
	Radius float64
}

type Rectangle struct {
	Width, Height float64
}

type Triangle struct {
	Base, Height float64
}

func (c Circle) Area() float64    { return 3.14159 * c.Radius * c.Radius }
func (r Rectangle) Area() float64 { return r.Width * r.Height }
func (t Triangle) Area() float64  { return 0.5 * t.Base * t.Height }

func describeShape(s Shape) {
	switch v := s.(type) {
	case Circle:
		fmt.Printf("Circle with radius=%.1f, area=%.2f\n", v.Radius, v.Area())
	case Rectangle:
		fmt.Printf("Rectangle %gx%g, area=%.2f\n", v.Width, v.Height, v.Area())
	case Triangle:
		fmt.Printf("Triangle base=%g height=%g, area=%.2f\n", v.Base, v.Height, v.Area())
	default:
		fmt.Printf("Unknown shape: %T\n", v)
	}
}

func safeGetRadius(s Shape) (float64, bool) {
	c, ok := s.(Circle)
	if !ok {
		return 0, false
	}
	return c.Radius, true
}

func main() {
	shapes := []Shape{
		Circle{Radius: 5},
		Rectangle{Width: 4, Height: 6},
		Triangle{Base: 3, Height: 8},
	}

	for _, s := range shapes {
		describeShape(s)
	}

	fmt.Println()
	for _, s := range shapes {
		if r, ok := safeGetRadius(s); ok {
			fmt.Printf("This is a circle with radius %.1f\n", r)
		} else {
			fmt.Printf("%T is not a circle\n", s)
		}
	}
}
